SELECT p.*, u.name AS user_name, u.email AS user_email, sp.plan_name, sp.plan_type FROM payments p LEFT JOIN users u ON p.user_id = u.user_id LEFT JOIN subscriptions s ON p.subscription_id = s.subscription_id LEFT JOIN subscription_plans sp ON s.plan_id = sp.plan_id
(u.name LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%'))
AND p.status = #{status}
ORDER BY p.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM payments p LEFT JOIN users u ON p.user_id = u.user_id
(u.name LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%'))
AND p.status = #{status}
